app.post('/usuarios', async (req, res) => {
  try {
    const { nome, email, senha } = req.body;

    // Hash da senha
    const senhaHash = await bcrypt.hash(senha, 10);

    const usuario = new Usuario({ nome, email, senha: senhaHash });
    await usuario.save();

