app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// ============================================
// Schema do Usuário
// ============================================
const userSchema = new mongoose.Schema({
    nome: {
        type: String,
        required: [true, 'O nome é obrigatório'],
        trim: true,
        minlength: [2, 'O nome deve ter no mínimo 2 caracteres'],
        maxlength: [100, 'O nome deve ter no máximo 100 caracteres']
    },
    email: {
        type: String,
        required: [true, 'O email é obrigatório'],
        unique: true,
        trim: true,
        lowercase: true,
        match: [/^\S+@\S+\.\S+$/, 'Por favor, insira um email válido']
    },
    senha: {
        type: String,
        required: [true, 'A senha é obrigatória'],
        minlength: [6, 'A senha deve ter no mínimo 6 caracteres'],
        select: false // Não retorna senha por padrão
    },
    idade: {
        type: Number,
        min: [0, 'A idade não pode ser negativa'],
        max: [150, 'A idade máxima é 150 anos']
    },
    ativo: {
        type: Boolean,
        default: true
    },
    role: {
        type: String,
        enum: ['usuario', 'admin', 'moderador'],
        default: 'usuario'
    }
}, {
    timestamps: true, // Adiciona createdAt e updatedAt automaticamente
