const CACHE_NAME = 'pwa-dynamic-cache-v1';
const PRECACHE_URLS = [
  '/',
  '/index.html',
  '/styles.css',
  '/app.js',
  '/manifest.json',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];
const API_CACHE = 'api-cache';
const API_PATTERN = new RegExp('/api/'); // adjust

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => cache.addAll(PRECACHE_URLS))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(
        keys.filter(key => key !== CACHE_NAME && key !== API_CACHE)
          .map(key => caches.delete(key))
      )
    ).then(() => self.clients.claim())
  );
});

// Cache first for static assets, network first for API with fallback to cache
self.addEventListener('fetch', event => {
  const {request} = event;
  if (request.mode === 'navigate') {
    // Navigation requests: try network, fallback to offline page
    event.respondWith(
      fetch(request).catch(() => caches.match('/offline.html'))
    );
    return;
