    });
    handlebars.registerHelper('ifEquals', (a, b, options) => {
      return a === b ? options.fn(this) : options.inverse(this);
    });
    handlebars.registerHelper('json', (context) => {
      return JSON.stringify(context, null, 2);
    });
  }

