      margin: options.margin || {
        top: '20mm',
        right: '15mm',
        bottom: '20mm',
        left: '15mm'
      },
      displayHeaderFooter: options.headerFooter !== false,
      headerTemplate: options.header || this.getDefaultHeader(options),
      footerTemplate: options.footer || this.getDefaultFooter(),
      preferCSSPageSize: true
    };

    await page.pdf(pdfOptions);
    await page.close();

