/**
 * Conversor de HTML/JSON para PDF
 * - Puppeteer para renderização precisa de HTML/CSS
 * - EJS para templates dinâmicos a partir de JSON
 */

const fs = require('fs');
const path = require('path');
const ejs = require('ejs');
const puppeteer = require('puppeteer');

class PdfConverter {
  constructor(options = {}) {
    this.options = {
      format: 'A4',
      printBackground: true,
      margin: { top: '20mm', right: '15mm', bottom: '20mm', left: '15mm' },
      ...options,
    };
  }

  /**
   * Converte arquivo HTML para PDF
   */
  async htmlToPdf(htmlPath, pdfPath) {
    if (!fs.existsSync(htmlPath)) {
      throw new Error(`Arquivo HTML não encontrado: ${htmlPath}`);
    }

    const html = fs.readFileSync(htmlPath, 'utf8');
    await this.renderPdf(html, pdfPath);
  }

  /**
   * Converte JSON + template EJS em PDF
   */
  async jsonToPdf(jsonPath, templatePath, pdfPath) {
    if (!fs.existsSync(jsonPath)) {
      throw new Error(`Arquivo JSON não encontrado: ${jsonPath}`);
    }
    if (!fs.existsSync(templatePath)) {
      throw new Error(`Template não encontrado: ${templatePath}`);
    }

    const data = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
    const template = fs.readFileSync(templatePath, 'utf8');

    const html = ejs.render(template, data, { filename: templatePath });
    await this.renderPdf(html, pdfPath);
  }

  /**
   * Renderiza HTML em PDF usando Puppeteer
   */
  async renderPdf(html, pdfPath) {
    const browser = await puppeteer.launch({
      headless: 'new',
      args: ['--no-sandbox', '--disable-setuid-sandbox'],
    });

    try {
      const page = await browser.newPage();
      await page.setContent(html, { waitUntil: 'networkidle0' });

      // Força renderização completa de tabelas e imagens
      await page.evaluate(async () => {
        await new Promise((resolve) => {
          const images = Array.from(document.images);
