          });
        });
      });

      await page.pdf({
        path: pdfPath,
        format: this.options.format,
        printBackground: this.options.printBackground,
        margin: this.options.margin,
      });

      console.log(`✔ PDF gerado: ${pdfPath}`);
    } finally {
      await browser.close();
    }
  }
}

